Translate("ruRU", "twilight-lord-kelris", {
	title = "Сумеречный владыка Келрис",
	subtitle = "Владыка Сумеречного Молота в Пучине",
	found = "Покои Лунного святилища, перед алтарем Древних богов",
	hint = "Ищите хозяина культа в святилище затопленного храма.",
	allegiance = "Сумеречный Молот",
	aliases = { "Келрис" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сумеречный владыка Келрис возглавляет {link:twilight-s-hammer}Сумеречный Молот{/link} в Непроглядной Пучине. Он сидит в трансе в святилище старого храма, возле алтаря, где культ совершает свои приношения. Под его властью сектанты приносят невинных в жертву гидре {link:aku-mai}Аку'май{/link} и взамен получают силу. Келрис владеет магией тени и сна и в бою способен п{link:ogres}огр{/link}узить своих врагов в беспомощную дрему.]=],
		},
		{
			title = "Значение",
			text = [=[Долгое время Келрис ускользал от {link:argent-dawn}Серебряного Рассвета{/link}. Его {link:the-night-watch}дозорные{/link} в {link:darnassus}Дарнассе{/link} говорят, что всякий раз, когда в этих землях показывалось зло, к нему был причастен Келрис, и годами они считали его мертвым или пропавшим. Он не был ни тем, ни другим. Он спустился в Пучину служить {red:old-gods}Древним богам{/red} и намеревался вернуть мир в хаос их эпохи. {link:tauren}Таурены{/link} {link:thunder-bluff}Громового Утеса{/link} называют его созданием чистого зла.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он привел {link:twilight-s-hammer}Сумеречный Молот{/link} в затопленный храм Элуны.
• Он заключил союз культа с {link:naga}нага{/link}ми Непроглядной пучины.
• Он приносил невинных в жертву гидре {link:aku-mai}Аку'май{/link} в обмен на силу.]=],
		},
	},
	chapters = {
		{
			title = "Донесение разведчика",
			hint = "Найдите в Пучине пропавшего разведчика Серебряного Рассвета.",
			text = [=[{link:argent-dawn}Серебряный Рассвет{/link} послал разведчика следить за храмом, и недели проходили без вестей. Когда его наконец нашли, он лежал раненый в пещерах, и силы его иссякли. Он узнал, что делает культ. {link:twilight-s-hammer}Сумеречный Молот{/link} и наги вместе удерживали руины, а их предводитель, Келрис, скармливал гидре невинных ради силы. Больше разведчик ничего не мог сделать. Он попросил, чтобы хозяина культа убили, а его голову вынесли из Пучины.]=],
		},
		{
			title = "Голова сумеречного владыки",
			hint = "Положите конец власти сумеречного владыки.",
			text = [=[Когда голову сумеречного владыки принесли Серебряному Рассвету в {link:darnassus}Дарнасс{/link}, страж рассвета Селгорм сказал, что наконец все встало на свои места: тот, кого они считали мертвым, все это время стоял за этим злом. Для Орды Башана Рунический Тотем возблагодарила Мать-Землю и сказала, что принести другого в жертву слуге Древних богов ради собственной выгоды — этому нет слов. Его смертью было спасено много невинных жизней.]=],
		},
	},
	mentions = {
		{ text = "Падение Сумерек" },
		{
			text = [=[Злодейство в Непроглядной Пучине, голова доставлена в {link:darnassus}Дарнасс{/link}]=],
		},
		{
			text = [=[Злодейство в Непроглядной Пучине, голова доставлена в {link:thunder-bluff}Громовой Утес{/link}]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Аку'май", note = "сила, которой он служит" },
		{ id = "argent-guard-thaelrid", name = "серебряный страж Таэлрид", note = "разведчик, который его раскрыл" },
		{ id = "lorgus-jett", name = "Лоргус Джетт", note = "слуга того же культа" },
	},
})

