		},
		{
			title = "Значение",
			text = [=[Морридун — доказательство того, что некоторые из павших перед Молотом могут повернуть назад.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Аку'май", note = "тварь, которой он когда-то хотел служить" },
	},
})

Translate("ruRU", "ghamoo-ra", {
	title = "Гхаму-ра",
	subtitle = "Истерзанная черепаха",
